command:
path=/var/lib/birbparty-authz
test "$(stat -c '%u:%g:%a' "$path")" = 65532:65532:750 && test -w "$path" && test -x "$path" || {
  echo 'Authorization mount requires operator-prepared 65532:65532 mode 0750' >&2; exit 1;
}
for file in "$path/runtime.json" "$path/runtime.json.tmp"; do
  test ! -L "$file" || {
    echo 'Authorization runtime path must not be a symlink; automatic repair is disabled' >&2; exit 1;
  }
  if test -e "$file"; then
    test -f "$file" && test "$(stat -c '%u:%g:%a' "$file")" = 65532:65532:640 &&
    test -r "$file" && test -w "$file" || {
      echo 'Authorization runtime file requires 65532:65532 mode 0640; automatic repair is disabled' >&2; exit 1;
    }
  fi
done

test "$(stat -c '%u:%g:%a' /var/lib/postgresql/data)" = 70:70:750 &&
test -w /var/lib/postgresql/data && test -x /var/lib/postgresql/data || {
  echo 'PostgreSQL mount requires operator-prepared 70:70 mode 0750' >&2; exit 1;
}
path=/var/lib/postgresql/data/pgdata
test ! -L "$path" || {
  echo 'PGDATA must not be a symlink; automatic repair is disabled' >&2; exit 1;
}
if test -e "$path"; then
  test -d "$path" && test "$(stat -c '%u:%g:%a' "$path")" = 70:70:700 &&
  test -w "$path" && test -x "$path" || {
    echo 'Existing PGDATA requires 70:70 mode 0700; automatic repair is disabled' >&2; exit 1;
  }
fi

test "$(stat -c '%u:%g:%a' /var/lib/postgresql/data)" = 70:70:750 &&
test -w /var/lib/postgresql/data && test -x /var/lib/postgresql/data || {
  echo 'PostgreSQL mount requires operator-prepared 70:70 mode 0750' >&2; exit 1;
}
path=/var/lib/postgresql/data/pgdata
test ! -L "$path" || {
  echo 'PGDATA must not be a symlink; automatic repair is disabled' >&2; exit 1;
}
if test -e "$path"; then
  test -d "$path" && test "$(stat -c '%u:%g:%a' "$path")" = 70:70:700 &&
  test -w "$path" && test -x "$path" || {
    echo 'Existing PGDATA requires 70:70 mode 0700; automatic repair is disabled' >&2; exit 1;
  }
fi
